"""Generate a C API forwarding table that loads native Dawn on demand."""

import re
from pathlib import Path


def generate_loader(header, helpers, platform="macos"):
    windows = platform == "windows"
    declarations = re.findall(r"^WGPU_EXPORT (.+?) (wgpu\w+)\((.*?)\) WGPU_FUNCTION_ATTRIBUTE;", header, re.MULTILINE)
    if not declarations:
        raise ValueError("Dawn SDK contains no WebGPU C API declarations")
    declarations += re.findall(r"^(WGPU\w+) (godot_webgpu_\w+)\((.*?)\);", helpers, re.MULTILINE)
    lines = [
        "// Generated by native_loader.py. Do not edit.",
        '#include "dawn_boundary.h"',
        '#include "platform/windows/windows.h"' if windows else "#include <dlfcn.h>",
        "static void *dawn_library = nullptr;",
    ]
    for result, name, parameters in declarations:
        arguments = (
            []
            if parameters == "void" or not parameters
            else [re.search(r"(\w+)$", part.strip()).group(1) for part in parameters.split(",")]
        )
        lines += [
            f"static decltype(&{name}) dawn_{name} = nullptr;",
            f'extern "C" {result} {name}({parameters}) {{ return dawn_{name}({", ".join(arguments)}); }}',
        ]
    lines += [
        "static bool load_native_dawn() {",
        "    if (dawn_library) { return true; }",
    ]
    if windows:
        lines += [
            "    HMODULE module = nullptr;",
            "    if (!GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT, reinterpret_cast<LPCWSTR>(&load_native_dawn), &module)) { return false; }",
            "    wchar_t filename[32768];",
            "    DWORD length = GetModuleFileNameW(module, filename, 32768);",
            "    if (!length || length >= 32768) { return false; }",
            '    const Char16String path = String::utf16(reinterpret_cast<const char16_t *>(filename), length).get_base_dir().path_join("godot_webgpu_dawn.dll").utf16();',
            "    HMODULE library = LoadLibraryExW(reinterpret_cast<LPCWSTR>(path.get_data()), nullptr, LOAD_LIBRARY_SEARCH_DLL_LOAD_DIR | LOAD_LIBRARY_SEARCH_DEFAULT_DIRS);",
        ]
        resolve = "GetProcAddress"
        close = "FreeLibrary"
    else:
        if platform == "macos":
            lines.append("    if (__builtin_available(macOS 13.0, *)) {} else { return false; }")
        runtime = "libgodot_webgpu_dawn.dylib" if platform == "macos" else "libgodot_webgpu_dawn.so"
        lines += [
            "    Dl_info module = {};",
            "    if (!dladdr(reinterpret_cast<const void *>(&load_native_dawn), &module) || !module.dli_fname) { return false; }",
            f'    const CharString path = String::utf8(module.dli_fname).get_base_dir().path_join("{runtime}").utf8();',
            "    void *library = dlopen(path.get_data(), RTLD_NOW | RTLD_LOCAL);",
        ]
        resolve = "dlsym"
        close = "dlclose"
    lines.append("    if (!library) { return false; }")
    for _, name, _ in declarations:
        lines += [
            f'    dawn_{name} = reinterpret_cast<decltype(dawn_{name})>({resolve}(library, "{name}"));',
            f"    if (!dawn_{name}) {{ {close}(library); return false; }}",
        ]
    lines += ["    dawn_library = library;", "    return true;", "}"]
    return "\n".join(lines) + "\n"


def build_loader(target, source, env):
    Path(str(target[0])).write_text(
        generate_loader(Path(str(source[0])).read_text(), Path(str(source[1])).read_text(), env["platform"])
    )
